//! CMYK output accuracy against an independent CMM (ADR-018).
//!
//! Expectations: `tests/fixtures/color/cmyk_expected.json`, generated by
//! `scripts/color/gen_cmyk_oracle.py` with LittleCMS 2.19 (Pillow 12.3.0 `ImageCms`) from the
//! bundled `Coated_Fogra39L_VIGC_300.icc` and Veskra's generated sRGB profile. All LittleCMS buffers
//! are 8-bit, so every comparison below includes up to half a code of LittleCMS quantization
//! (0.2 % ink, 0.2 L*, 0.5 a*/b*). Run with `-- --nocapture` for the measured numbers.
//!
//! Statistics: "channel" = |Veskra − LittleCMS| over every C, M, Y, K value of every swatch, in
//! percent ink; median = mean of the two middle values; p95 = nearest rank.

#![allow(clippy::unwrap_used, clippy::needless_range_loop)]

use serde::Deserialize;
use std::path::PathBuf;
use std::sync::Arc;
use veskra_color::cmyk::{CmykProfile, CmykTransform, GAMUT_DELTA_E00, LINK_GRID_POINTS};
use veskra_color::icc::IccProfile;
use veskra_color::lab::{ciede2000, srgb8_to_lab_d50};
use veskra_color::transform::RenderingIntent;

#[derive(Deserialize)]
struct Doc {
    tools: serde_json::Value,
    profile: ProfileDoc,
    swatches: Vec<Swatch>,
    rgb_to_cmyk: Vec<RgbToCmyk>,
    cmyk_grid: Vec<[u8; 4]>,
    cmyk_to_lab: Vec<CmykToLab>,
    cmyk_to_srgb: Vec<CmykToSrgb>,
    synthetic_v4: Synthetic,
}

#[derive(Deserialize)]
struct ProfileDoc {
    sha256: String,
    lcms_description: String,
    bytes: usize,
}

#[derive(Deserialize)]
struct Swatch {
    category: String,
    rgb8: [u8; 3],
}

#[derive(Deserialize)]
struct RgbToCmyk {
    intent: String,
    bpc: bool,
    lcms_flags: String,
    cmyk8: Vec<[u8; 4]>,
}

#[derive(Deserialize)]
struct CmykToLab {
    set: String,
    intent: String,
    lab: Vec<[f64; 3]>,
}

#[derive(Deserialize)]
struct CmykToSrgb {
    intent: String,
    bpc: bool,
    rgb8: Vec<[u8; 3]>,
}

#[derive(Deserialize)]
struct Synthetic {
    file: String,
    lcms_description: String,
    rgb_to_cmyk_relative: Vec<[u8; 4]>,
    cmyk_to_lab_relative: Vec<[f64; 3]>,
}

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/color")
}

fn doc() -> Doc {
    serde_json::from_str(&std::fs::read_to_string(fixtures().join("cmyk_expected.json")).unwrap()).unwrap()
}

#[derive(Debug, Clone, Copy)]
struct Stats {
    median: f64,
    p95: f64,
    max: f64,
    n: usize,
}

fn stats(mut v: Vec<f64>) -> Stats {
    v.sort_by(f64::total_cmp);
    let n = v.len();
    let median = if n.is_multiple_of(2) { (v[n / 2 - 1] + v[n / 2]) / 2.0 } else { v[n / 2] };
    let p95 = v[((0.95 * n as f64).ceil() as usize).clamp(1, n) - 1];
    Stats { median, p95, max: v[n - 1], n }
}

fn intent(name: &str) -> RenderingIntent {
    match name {
        "perceptual" => RenderingIntent::Perceptual,
        _ => RenderingIntent::RelativeColorimetric,
    }
}

fn transform(i: RenderingIntent, bpc: bool) -> CmykTransform {
    CmykTransform::new(&IccProfile::srgb(), CmykProfile::bundled().unwrap(), i, bpc).unwrap()
}

fn rgbf(c: [u8; 3]) -> [f64; 3] {
    c.map(|v| v as f64 / 255.0)
}

/// Channel differences in percent ink between our values (0..1) and LittleCMS 8-bit values.
fn channel_diffs(ours: &[[f64; 4]], lcms: &[[u8; 4]]) -> Vec<f64> {
    let mut d = Vec::with_capacity(ours.len() * 4);
    for (o, l) in ours.iter().zip(lcms) {
        for k in 0..4 {
            d.push((o[k] * 100.0 - l[k] as f64 * 100.0 / 255.0).abs());
        }
    }
    d
}

#[test]
fn bundled_profile_matches_the_fixture() {
    let d = doc();
    let p = CmykProfile::bundled().unwrap();
    assert_eq!(p.bytes().len(), d.profile.bytes);
    // Byte-for-byte: the oracle checked this SHA-256 of the committed file.
    assert_eq!(d.profile.sha256, "6df43849a84d2632e7900a125f657bd09364ed56775bc4740c1e39a5492d47e3");
    assert_eq!(p.description(), d.profile.lcms_description);
    println!("oracle tools: {}", d.tools);
}

/// RGB → CMYK, direct pipeline and device link, every intent / BPC combination.
#[test]
fn rgb_to_cmyk_matches_littlecms() {
    let d = doc();
    let rgb: Vec<[u8; 3]> = d.swatches.iter().map(|s| s.rgb8).collect();
    assert!(rgb.len() >= 512, "{} swatches", rgb.len());
    for cat in ["primary", "neutral", "near-black", "near-white", "out-of-gamut"] {
        assert!(d.swatches.iter().any(|s| s.category == cat), "{cat}");
    }
    println!(
        "{:<22} {:<5} {:<10} | {:>26} | {:>26}",
        "intent", "bpc", "lcms", "direct: median/p95/max %", "33^3 link: median/p95/max %"
    );
    for set in &d.rgb_to_cmyk {
        let t = transform(intent(&set.intent), set.bpc);
        let direct: Vec<[f64; 4]> = rgb.iter().map(|c| t.rgb_to_cmyk(rgbf(*c))).collect();
        let link: Vec<[f64; 4]> = rgb
            .iter()
            .map(|c| {
                let v = t.link().eval(c.map(|x| x as f32 / 255.0));
                [v[0] as f64, v[1] as f64, v[2] as f64, v[3] as f64]
            })
            .collect();
        let sd = stats(channel_diffs(&direct, &set.cmyk8));
        let sl = stats(channel_diffs(&link, &set.cmyk8));
        println!(
            "{:<22} {:<5} {:<10} | {:>8.3} {:>8.3} {:>8.3} | {:>8.3} {:>8.3} {:>8.3}",
            set.intent, set.bpc, set.lcms_flags, sd.median, sd.p95, sd.max, sl.median, sl.p95, sl.max
        );
        // ADR-018 targets: median ≤ 1 %, p95 ≤ 2 %, max ≤ 4 %. The full-precision LittleCMS pipeline
        // (NOOPTIMIZE) is compared with our direct pipeline, its default 33³ link with ours.
        let s = if set.lcms_flags == "NOOPTIMIZE" { sd } else { sl };
        assert!(
            s.median <= 1.0 && s.p95 <= 2.0 && s.max <= 4.0,
            "{} bpc={} {}: {s:?}",
            set.intent,
            set.bpc,
            set.lcms_flags
        );
        assert_eq!(s.n, rgb.len() * 4);
        // White paper stays ink-free.
        let w = rgb.iter().position(|c| *c == [255, 255, 255]).unwrap();
        assert!(direct[w].iter().all(|v| *v < 0.5 / 255.0), "white {:?}", direct[w]);
    }
}

/// CMYK → Lab against LittleCMS for a 5⁴ CMYK grid, and the sRGB → CMYK → Lab round trip.
#[test]
fn cmyk_to_lab_matches_littlecms() {
    let d = doc();
    let p = CmykProfile::bundled().unwrap();
    for set in &d.cmyk_to_lab {
        let inputs: Vec<[u8; 4]> = if set.set == "grid" {
            d.cmyk_grid.clone()
        } else {
            d.rgb_to_cmyk
                .iter()
                .find(|s| s.intent == "relative-colorimetric" && s.bpc && s.lcms_flags == "NOOPTIMIZE")
                .unwrap()
                .cmyk8
                .clone()
        };
        let de: Vec<f64> = inputs
            .iter()
            .zip(&set.lab)
            .map(|(c, l)| ciede2000(p.cmyk_to_lab(c.map(|v| v as f64 / 255.0), intent(&set.intent)), *l))
            .collect();
        let s = stats(de);
        println!(
            "CMYK->Lab {:<16} {:<22} dE00 median {:.3} p95 {:.3} max {:.3} (n={})",
            set.set, set.intent, s.median, s.p95, s.max, s.n
        );
        assert!(s.median <= 0.5, "{} {}: {s:?}", set.set, set.intent);
        assert!(s.p95 <= 1.0 && s.max <= 2.0, "{} {}: {s:?}", set.set, set.intent);
    }
    // Full round trip: our sRGB → CMYK → Lab vs LittleCMS's (both relative + BPC).
    let t = transform(RenderingIntent::RelativeColorimetric, true);
    let lcms = d.cmyk_to_lab.iter().find(|s| s.set == "swatch_roundtrip").unwrap();
    let de: Vec<f64> = d
        .swatches
        .iter()
        .zip(&lcms.lab)
        .map(|(s, l)| ciede2000(t.cmyk_to_lab(t.rgb_to_cmyk(rgbf(s.rgb8))), *l))
        .collect();
    let s = stats(de);
    println!("sRGB->CMYK->Lab round trip vs LittleCMS: dE00 median {:.3} p95 {:.3} max {:.3}", s.median, s.p95, s.max);
    assert!(s.median <= 0.5, "{s:?}");
}

/// CMYK → sRGB (color picker direction).
#[test]
fn cmyk_to_srgb_matches_littlecms() {
    let d = doc();
    for set in &d.cmyk_to_srgb {
        let t = transform(intent(&set.intent), set.bpc);
        let mut diffs = Vec::new();
        let mut de = Vec::new();
        for (c, l) in d.cmyk_grid.iter().zip(&set.rgb8) {
            let (rgb, _) = t.cmyk_to_rgb(c.map(|v| v as f64 / 255.0));
            let ours = rgb.map(|v| (v * 255.0 + 0.5).floor() as i32);
            for k in 0..3 {
                diffs.push((ours[k] - l[k] as i32).abs() as f64);
            }
            de.push(ciede2000(srgb8_to_lab_d50(ours.map(|v| v as u8)), srgb8_to_lab_d50(*l)));
        }
        let s = stats(diffs);
        let e = stats(de);
        println!(
            "CMYK->sRGB {:<22} bpc={:<5} 8-bit code diff median {:.1} p95 {:.1} max {:.1}; dE00 median {:.3} p95 {:.3} max {:.3}",
            set.intent, set.bpc, s.median, s.p95, s.max, e.median, e.p95, e.max
        );
        assert!(e.median <= 0.5 && e.p95 <= 1.5, "{} bpc={}: {e:?}", set.intent, set.bpc);
    }
}

/// Accuracy cost of the precomputed device link against the direct pipeline (dense sample).
#[test]
fn device_link_accuracy_cost() {
    for (i, bpc) in [(RenderingIntent::RelativeColorimetric, true), (RenderingIntent::Perceptual, true)] {
        let t = transform(i, bpc);
        let link = t.link();
        assert_eq!(link.grid_points(), LINK_GRID_POINTS);
        let mut ink = Vec::new();
        let mut de = Vec::new();
        let mut gamut_disagree = 0usize;
        let mut n = 0usize;
        // 0..=255 in steps of 5 on every axis (52³ = 140 608 colors, off the 33-point grid).
        for r in (0..=255).step_by(5) {
            for g in (0..=255).step_by(5) {
                for b in (0..=255).step_by(5) {
                    let rgb = [r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0];
                    let (exact, exact_de) = t.rgb_to_cmyk_with_delta_e(rgb);
                    let v = link.eval(rgb.map(|x| x as f32));
                    let approx = [v[0] as f64, v[1] as f64, v[2] as f64, v[3] as f64];
                    let worst = (0..4).map(|k| (exact[k] - approx[k]).abs() * 100.0).fold(0.0, f64::max);
                    ink.push(worst);
                    de.push(ciede2000(t.cmyk_to_lab(exact), t.cmyk_to_lab(approx)));
                    if (exact_de > GAMUT_DELTA_E00) != (v[4] as f64 > GAMUT_DELTA_E00) {
                        gamut_disagree += 1;
                    }
                    n += 1;
                }
            }
        }
        let (s, e) = (stats(ink), stats(de));
        println!(
            "33^3 link vs direct ({:?}, bpc={bpc}): max-channel ink % median {:.3} p95 {:.3} max {:.3}; dE00 of the inks median {:.3} p95 {:.3} max {:.3}; gamut flag differs for {gamut_disagree} of {n}",
            i, s.median, s.p95, s.max, e.median, e.p95, e.max
        );
        assert!(e.p95 <= 1.0, "{e:?}");
    }
}

/// ICC v4 `mAB `/`mBA ` (curv + para curves, matrix with offset, 16- and 8-bit CLUTs, non-uniform
/// grid) parsed by Veskra and evaluated by LittleCMS.
#[test]
fn synthetic_v4_profile_matches_littlecms() {
    let d = doc();
    let bytes = std::fs::read(fixtures().join(&d.synthetic_v4.file)).unwrap();
    let p = Arc::new(CmykProfile::parse(&bytes).unwrap());
    assert_eq!(p.version().major, 4);
    assert_eq!(p.description(), d.synthetic_v4.lcms_description);
    // Only A2B0/B2A0 exist: relative colorimetric falls back to them, as in LittleCMS.
    assert!(!p.has_table(RenderingIntent::RelativeColorimetric, true));
    let t = CmykTransform::new(&IccProfile::srgb(), p.clone(), RenderingIntent::RelativeColorimetric, false).unwrap();
    let ours: Vec<[f64; 4]> = d.swatches.iter().map(|s| t.rgb_to_cmyk(rgbf(s.rgb8))).collect();
    let s = stats(channel_diffs(&ours, &d.synthetic_v4.rgb_to_cmyk_relative));
    println!("synthetic v4 sRGB->CMYK: channel % median {:.3} p95 {:.3} max {:.3}", s.median, s.p95, s.max);
    assert!(s.max <= 0.6, "{s:?}");
    let de: Vec<f64> = d
        .cmyk_grid
        .iter()
        .zip(&d.synthetic_v4.cmyk_to_lab_relative)
        .map(|(c, l)| ciede2000(p.cmyk_to_lab(c.map(|v| v as f64 / 255.0), RenderingIntent::RelativeColorimetric), *l))
        .collect();
    let e = stats(de);
    println!("synthetic v4 CMYK->Lab: dE00 median {:.3} p95 {:.3} max {:.3}", e.median, e.p95, e.max);
    assert!(e.max <= 1.0, "{e:?}");
}
